  "ecological": ["էկոլոգիական", "Նավթի արտահոսքի էկոլոգիական ազդեցությունը կործանարար էր տեղի ծովային կյանքի համար։", "ekologiakan"],
  "economic growth": ["տնտեսական աճ", "Ուժեղ տնտեսական աճը հանգեցրեց գործազրկության նվազման ամբողջ երկրում։", "tntesakan ach"],
  "economies of scale": ["մասշտաբի տնտեսում", "Խոշոր ընկերությունները օգտվում են մասշտաբի տնտեսումից։", "masshtabi tntesum"],
  "economy": ["տնտեսություն", "Վերջին տասնամյակում երկրի տնտեսությունը կայուն աճել է։", "tntesut'yun"],
  "ecosystem": ["էկոհամակարգ", "Անտառային էկոհամակարգը կախված է տեսակների հավասարակշռությունից։", "ekohamakarg"],
  "ecotourism": ["էկոզբոսաշրջություն", "Էկոզբոսաշրջությունն աջակցում է բնապահպանությանը՝ եկամուտ ստեղծելով տեղական համայնքների համար։", "ekozbosashrjut'yun"],
  "ecstasy": ["էքստազ; հիացմունք", "Լուրը լսելով՝ նա հիացմունքից իրեն չէր գտնում։", "ek'staz; hiats'munk'"],
  "edge": ["եզր; առավելություն", "Նա զգուշորեն քայլում էր բարձր ժայռոտ արահետի եզրով։", "yezr; arravelut'yun"],
  "edge out": ["աննշան առավելությամբ գերազանցել", "Նա աննշան տարբերությամբ գերազանցեց իր մրցակցին։", "annshan arravelut'yamb gerazants'el"],
  "edible": ["ուտելի", "Ոչ բոլոր վայրի սնկերն են ուտելի, ուստի պետք է զգույշ լինել։", "uteli"],
  "edit": ["խմբագրել; մոնտաժել", "Նա ամբողջ կեսօրն անցկացրեց իր շարադրությունը խմբագրելով, նախքան հանձնելը։", "khmbagrel; montazhel"],
  "editorial": ["խմբագրական; առաջնորդող հոդված", "Խմբագրականը կոչ էր անում կլիմայական քաղաքականության մեջ ավելի վճռական գործողությունների։", "khmbagrakan; arrajnordogh hodvats"],
