  "eggplant": ["սմբուկ", "Սմբուկը խորովվեց և մատուցվեց մածունով սոուսով։", "smbuk"],
  "egotistical": ["եսակենտրոն; ինքնասեր", "Նրա եսակենտրոն վերաբերմունքը օտարեց թիմի անդամներին։", "yesakentron; ink'naser"],
  "egregious": ["ակնհայտ; սարսափելի", "Դատավորը հանցագործությունը որակեց որպես իշխանության ակնհայտ չարաշահում։", "aknhayt; sarsap'eli"],
  "Egyptian": ["եգիպտացի", "Եգիպտացի հնագետը հայտնաբերեց նախկինում անհայտ դամբարան։", "yegiptats'i"],
  "eight": ["ութ", "Հանդիպումը սկսվում է առավոտյան ժամը ութին։", "ut'"],
  "either": ["երկուսից մեկը; նույնպես", "Երկու տարբերակներից յուրաքանչյուրը կաշխատի, ուստի պարզապես ընտրիր քո նախընտրածը։", "yerkusits' meke; nuynpes"],
  "eject": ["դուրս նետել; արտանետվել", "Վթարային իրավիճակում օդաչուն ստիպված էր կատապուլտով դուրս նետվել ինքնաթիռից։", "durs netel; artanetvel"],
  "elaborate": ["մանրամասնել; մանրամասն", "Կարո՞ղ եք մանրամասնել շուկայական միտումների վերաբերյալ ձեր տեսակետը։", "manramasnel; manramasn"],
  "elaborate (on)": ["մանրամասնել", "Կարո՞ղ եք խնդրեմ մանրամասնել ձեր առաջարկի հիմնական կետերը։", "manramasnel"],
  "elaboration": ["մշակում; մանրամասնում", "Հաստատումից առաջ անհրաժեշտ էր ծրագրի հետագա մանրամասնում։", "mshakum; manramasnum"],
  "elastic": ["առաձգական; ռետին", "Ռետինը պայթեց, երբ նա չափազանց ձգեց այն։", "arradzgakan; rretin"],
  "elate": ["ոգևորել; հրճվանք պատճառել", "Նրա հաղթանակի լուրը ոգևորեց ամբողջ թիմին։", "vogevorel; hrchvank' patcharrel"],
  "elation": ["ցնծություն; հրճվանք", "Լուրը լսելով՝ նա չէր կարողանում թաքցնել իր ցնծությունը։", "ts'ntsut'yun; hrchvank'"],
  "elbow": ["արմունկ", "Նա պատահաբար արմունկով դիպավ գրասեղանի սուր եզրին։", "armunk"],
  "elder": ["ավագ; տարեց", "Նա միշտ հարգում էր գյուղի ավագի տված խորհուրդները։", "avag; tarets'"],
  "elderly": ["տարեց", "Ծրագիրը տարեց բնակիչներին սնունդ և աջակցություն է տրամադրում։", "tarets'"],
  "elect": ["ընտրել", "Քաղաքացիները առաջիկա ընտրություններում նոր նախագահ կընտրեն։", "entrel"],
  "election": ["ընտրություններ", "Անցյալ ամիս միլիոնավոր մարդիկ քվեարկեցին համապետական ընտրություններում։", "entrut'yunner"],
  "electoral": ["ընտրական", "Նոր ընտրական համակարգը ներդրվեց հաջորդ համապետական ընտրություններից առաջ։", "entrakan"],
  "electrician": ["էլեկտրիկ", "Էլեկտրիկը շտկեց հյուրասենյակի անսարք էլեկտրալարերը։", "elektrik"],
  "electricity": ["էլեկտրաէներգիա; հոսանք", "Փոթորիկը ամբողջ թաղամասն էլեկտրաէներգիայից զրկեց։", "elektraenergia; hosank'"],
