  "stern": ["խիստ; նավախել", "Նրա խիստ արտահայտությունը պարզ էր դարձնում, որ նա կատակելու տրամադրություն չունի։", "khist; navakhel"],
  "stew": ["շոգեխաշել; ռագու", "Ընթրիքի համար նա արմատապտուղներով տավարի մսի հագեցնող շոգեխաշել պատրաստեց։", "shogekhashel; rragu"],
  "stick": ["փայտ; կպչել; կպցնել", "Նա սառնարանին գրություն կպցրեց՝ իրեն հիշեցնելու ընդունելության մասին։", "p'ayt; kpch'el; kpts'nel"],
  "stick (stuck, stuck)": ["խրվել; կպչել; փայտ", "Դարակը խրվել էր, և նա բոլորովին չէր կարողանում բացել այն։", "khrvel; kpch'el; p'ayt"],
  "stick at": ["համառորեն շարունակել", "Չնայած դանդաղ վաղ առաջընթացին՝ նա համառորեն շարունակեց գործիքը սովորել։", "hamarroren sharunakel"],
