  "stick up for": ["պաշտպանել", "Հանդիպմանը նա միակ մարդն էր, ով պաշտպանեց նրան։", "pashtpanel"],
  "stiff": ["կոշտ; կարծրացած", "Մի քանի ժամային գոտի անցնող երկար թռիչքից հետո նրա մկանները կոշտացել էին։", "kosht; kartsrats'ats"],
  "stifle": ["խեղդել; ճնշել", "Նոր կանոնակարգերը սպառնում էին խեղդել նորարարությունը ամբողջ ոլորտում։", "kheghdel; chnshel"],
  "stigma": ["խարան", "Հոգեկան հիվանդության հետ դեռ խարան է կապված։", "kharan"],
  "stigmatize": ["խարանել", "Շատ հասարակություններում հոգեկան հիվանդությունը դեռ խարանվում է։", "kharanel"],
  "still": ["դեռ; անշարժ", "Նախագիծը սկսվելուց երեք ամիս անց նա դեռ աշխատում է դրա վրա։", "derr; ansharzh"],
  "stimulate": ["խթանել", "Նոր ծրագիրը նախատեսված էր երիտասարդ սովորողների մոտ ստեղծագործականությունը խթանելու համար։", "kht'anel"],
  "stimulation": ["խթանում", "Մտավոր խթանումը կարևոր է ճանաչողական առողջությունը պահպանելու համար։", "kht'anum"],
  "stimulus": ["խթան", "Վերականգնումը խթանելու համար կառավարությունը տնտեսական խթանման փաթեթ ներդրեց։", "kht'an"],
  "sting (stung, stung)": ["խայթել; խայթոց", "Այգում աշխատելիս նրան իշամեղու խայթեց։", "khayt'el; khayt'ots'"],
  "stingy": ["ժլատ; ագահ", "Նա չափազանց ժլատ է՝ որևէ մեկին երբևէ սուրճ հյուրասիրելու համար։", "zhlat; agah"],
  "stink (stank, stunk)": ["գարշահոտել", "Ամառային շոգին նրբանցքի աղբամանները գարշահոտում էին։", "garshahotel"],
  "stint": ["ժամանակահատված; աշխատանքի շրջան", "Նա արտասահմանում բարեգործական կազմակերպությունում վեցամսյա աշխատանքի շրջան անցավ։", "zhamanakahatvats; ashkhatank'i shrjan"],
  "stir": ["խառնել; հուզել", "Հայտարարությունը ամբողջ երկրում զգալի վեճ առաջացրեց։", "kharrnel; huzel"],
  "stir up": ["հրահրել; բորբոքել", "Վիճահարույց ելույթը ամբոխի մեջ ուժեղ հույզեր բորբոքեց։", "hrahrel; borbok'el"],
  "stir-fry": ["արագ տապակել խառնելով", "Բանջարեղենը արագ տապակեք խառնելով, մինչև փափկի։", "arag tapakel kharrnelov"],
